export type GenerateTextInput = {
  messages: JsonModelMessage[]
  systemPrompt?: string
  tools: ToolSet
}

export function prepareGenerateTextRequest(input: Pick<GenerateTextInput, 'messages' | 'systemPrompt'>, provider: string, modelId: string) {
  const systemMessages: string[] = []
  const nonSystemMessages: JsonModelMessage[] = []

  for (const message of input.messages) {
    if (message.role === 'system') {
      systemMessages.push(message.content)
    } else {
      nonSystemMessages.push(message)
    }
  }

  const system = [input.systemPrompt, ...systemMessages].filter((part) => part && part.length > 0).join('\n\n') || undefined
  const messages = applyCacheControl(nonSystemMessages.map(fromJsonModelMessage), provider, modelId)

  return { system, messages }
}

async function createPullRequest(input: { title: string; description: string }, _context: ToolCallContext) {
  spawnSync('gh', ['pr', 'create', '--title', input.title, '--body', input.description], {
    stdio: 'inherit',
  })
  return { title: input.title, description: input.description }
}

async function createCommit(input: { message: string }, _context: ToolCallContext) {
  const result = spawnSync('git', ['commit', '-m', input.message], {
    stdio: 'inherit',
  })
  if (result.status !== 0) {
    throw new Error('Commit failed')
  }
  return { message: input.message }
}

async function printChangeFile(_input: unknown, context: ToolCallContext) {
  const { stagedFiles, unstagedFiles } = getLocalChanges()
  if (stagedFiles.length === 0 && unstagedFiles.length === 0) {
    context.workflowContext.logger.info('No changes to commit.')
  } else {
    if (stagedFiles.length > 0) {
      context.workflowContext.logger.info('Staged files:')
      for (const file of stagedFiles) {
        context.workflowContext.logger.info(`- ${file.status}: ${file.path}`)
      }
    }
    if (unstagedFiles.length > 0) {
      context.workflowContext.logger.info('\nUnstaged files:')
      for (const file of unstagedFiles) {
        context.workflowContext.logger.info(`- ${file.status}: ${file.path}`)
      }
    }
  }
  return { stagedFiles, unstagedFiles }
}

async function confirm(input: { message: string }, context: ToolCallContext) {
  if (context.yes) {
    return true
  }

  // to allow ora to fully stop the spinner so inquirer can takeover the cli window
  await new Promise((resolve) => setTimeout(resolve, 50))
  process.stderr.write('\u0007')
  return await inquirerConfirm({ message: input.message })
}

async function input(input: { message: string; default: string }, context: ToolCallContext) {
  if (context.yes) {
    return input.default ?? ''
  }

  // to allow ora to fully stop the spinner so inquirer can takeover the cli window
  await new Promise((resolve) => setTimeout(resolve, 50))
  process.stderr.write('\u0007')
  const result = await getUserInput(input.message, {
    default: input.default,
  })

  if (result === undefined) {
    throw new UserCancelledError()
  }
  return result
}

async function select(input: { message: string; choices: { name: string; value: string }[] }, context: ToolCallContext) {
  if (context.yes) {
    return input.choices[0].value
  }

  // to allow ora to fully stop the spinner so inquirer can takeover the cli window
  await new Promise((resolve) => setTimeout(resolve, 50))
  process.stderr.write('\u0007')
  return await inquirerSelect({ message: input.message, choices: input.choices })
}

async function executeCommand(input: CliToolRegistry['executeCommand']['input']) {
  return new Promise<{ exitCode: number; stdout: string; stderr: string }>((resolve, reject) => {
    const child =
      input.shell === true
        ? spawn(input.command, { shell: true, stdio: 'pipe' })
        : spawn(input.command, input.args, { shell: false, stdio: 'pipe' })

    let stdout = ''
    let stderr = ''
    child.stdout.setEncoding('utf8')
    child.stdout.on('data', (data: string) => {
      if (input.pipe) {
        process.stdout.write(data)
      }
      stdout += data
    })
    child.stderr.setEncoding('utf8')
    child.stderr.on('data', (data: string) => {
      if (input.pipe) {
        process.stderr.write(data)
      }
      stderr += data
    })

    child.on('close', (code: number | null) => {
      resolve({ exitCode: code ?? -1, stdout, stderr })
    })

    child.on('error', (err: Error) => {
      reject(err)
    })
  })
}

async function generateText(input: GenerateTextInput, context: ToolCallContext) {
  const { model, agentCallback } = context
  if (!model) {
    throw new Error('Model not found in context')
  }

  const { retryCount = 5, requestTimeoutSeconds = 90 } = context.parameters
  const maxAttempts = retryCount + 1

  const prompt = prepareGenerateTextRequest(input, model.provider, model.modelId)
  const usageMeter = context.parameters.usageMeter

  // Repetition detection constants
  const REPETITION_DETECTION_WINDOW = 20
  const REPETITION_CHECK_HALF = 10
  const REPETITION_MIN_LENGTH = 20

  let lastError: Error | undefined

  for (let i = 0; i < maxAttempts; i++) {
    const hasAnotherAttempt = i + 1 < maxAttempts
    await usageMeter.waitForPending()
    const limitResult = usageMeter.isLimitExceeded()
    if (limitResult.cost) {
      agentCallback?.({
        kind: TaskEventKind.UsageExceeded,
      })
      throw new QuotaExceededError(model.provider, model.modelId, usageMeter.usage.cost, limitResult.maxCost)
    }
    if (!usageMeter.tryReserveMessage()) {
      agentCallback?.({
        kind: TaskEventKind.UsageExceeded,
      })
      throw new MessageLimitExceededError(model.provider, model.modelId, usageMeter.usage.messageCount, limitResult.maxMessages)
    }

    const abortController = new AbortController()
    let timeoutError: ProviderTimeoutError | undefined
    const abortForTimeout = () => {
      if (abortController.signal.aborted) {
        return
      }
      timeoutError = new ProviderTimeoutError(model.provider, model.modelId, requestTimeoutSeconds)
      abortController.abort(timeoutError)
    }
    let timeout = setTimeout(abortForTimeout, requestTimeoutSeconds * 1000)

    const lastOutputs: string[] = []
    let repetitionError: Error | undefined
    let streamError: Error | undefined
    const captureStreamError = (error: unknown) => {
      context.workflowContext.logger.error('Error in stream:', error)
      streamError = error instanceof Error ? error : new Error(String(error))
    }

    const usageMeterOnFinishHandler = usageMeter.onFinishHandler(model, { messageAlreadyCounted: true })

    try {
      const stream = streamText({
        model,
        temperature: 0,
        system: prompt.system,
        messages: prompt.messages,
        tools: input.tools,
        async onChunk({ chunk }) {
          clearTimeout(timeout)
          timeout = setTimeout(abortForTimeout, requestTimeoutSeconds * 1000)
          switch (chunk.type) {
            case 'text-delta':
              lastOutputs.push(chunk.text)
              if (lastOutputs.length > REPETITION_DETECTION_WINDOW) {
                lastOutputs.shift()
              }
              if (lastOutputs.length === REPETITION_DETECTION_WINDOW) {
                const firstHalf = lastOutputs.slice(0, REPETITION_CHECK_HALF).join('')
                const secondHalf = lastOutputs.slice(REPETITION_CHECK_HALF).join('')
                if (firstHalf === secondHalf) {
                  if (firstHalf.length > REPETITION_MIN_LENGTH) {
                    if (!abortController.signal.aborted) {
                      repetitionError = new Error('Repetition detected in model output')
                      abortController.abort(repetitionError)
                    }
                  }
                }
              }
              agentCallback?.({
                kind: TaskEventKind.Text,
                newText: chunk.text,
              })
              break
            case 'reasoning-delta':
              agentCallback?.({
                kind: TaskEventKind.Reasoning,
                newText: chunk.text,
              })
              break
          }
        },
        onFinish(result) {
          usageMeterOnFinishHandler?.(result)
        },
        onError: ({ error }) => captureStreamError(error),
        providerOptions: context.parameters.providerOptions,
        abortSignal: abortController.signal,
      })

      await stream.consumeStream({
        onError: captureStreamError,
      })

      const resp = await stream.response
      return resp.messages.map(toJsonModelMessage)
    } catch (error: unknown) {
      if (repetitionError) {
        if (hasAnotherAttempt) context.workflowContext.logger.warn('Repetition detected, retrying...')
        lastError = repetitionError
        continue
      }

      if (timeoutError) {
        if (hasAnotherAttempt) {
          context.workflowContext.logger.warn(`Request timed out after ${requestTimeoutSeconds} seconds, retrying...`)
        }
        lastError = timeoutError
        continue
      }

      const requestError = streamError ?? error

      // Handle HTTP errors
      if (APICallError.isInstance(requestError) && requestError.statusCode !== undefined) {
        const statusCode = requestError.statusCode

        // Create appropriate error based on status code
        const providerError = createProviderErrorFromStatus(model.provider, model.modelId, statusCode, requestError)

        // Only retry if error is retryable
        if (providerError.retryable && (statusCode === 429 || statusCode >= 500)) {
          lastError = providerError

          if (hasAnotherAttempt) {
            context.workflowContext.logger.warn(`${providerError.message} (attempt ${i + 1}/${maxAttempts})`)
            const backoff = computeRateLimitBackoffSeconds(i)
            context.workflowContext.logger.debug(`Waiting ${backoff}s before retry...`)
            await new Promise((resolve) => setTimeout(resolve, backoff * 1000))
          }
          continue
        }

        // Non-retryable HTTP error - throw immediately
        throw providerError
      }

      // Handle other errors
      if (requestError instanceof Error) {
        // Check for network errors
        if (
          requestError.message.includes('ECONNREFUSED') ||
          requestError.message.includes('ENOTFOUND') ||
          requestError.message.includes('ETIMEDOUT')
        ) {
          if (hasAnotherAttempt) context.workflowContext.logger.warn(`Network error: ${requestError.message}, retrying...`)
          lastError = requestError
          continue
        }

        // Unknown error - save and continue to retry
        if (hasAnotherAttempt) context.workflowContext.logger.warn(`Unexpected error: ${requestError.message}, retrying...`)
        lastError = requestError
        continue
      }

      // Non-Error throwable
      lastError = new Error(String(requestError))
    } finally {
      clearTimeout(timeout)
    }
  }

  // All retries exhausted
  throw new MaxRetriesExceededError(model.provider, model.modelId, maxAttempts, lastError || new Error('Unknown error'))
}

async function invokeTool(input: AgentToolRegistry['invokeTool']['input'], context: ToolCallContext): Promise<ToolResponse> {
  const tool = toolHandlers.get(input.toolName)
  if (!tool) {
    return {
      success: false,
      message: {
        type: 'error-text',
        value: `Tool not found: ${input.toolName}`,
      },
    }
  }
  try {
    const result = await tool.handler(context.toolProvider, input.input as Partial<Record<string, ToolParameterValue>>)
    return result
  } catch (error: unknown) {
    return {
      success: false,
      message: {
        type: 'error-text',
        value: error instanceof Error ? error.message : String(error),
      },
    }
  }
}

async function taskEvent(input: TaskEvent, context: ToolCallContext) {
  await context.agentCallback?.(input)
}

async function getMemoryContext(_input: unknown, context: ToolCallContext) {
  const { listMemoryTopics, readMemory } = context.toolProvider
  if (!listMemoryTopics || !readMemory) {
    throw new Error('Memory provider is not available')
  }
  const topics = await listMemoryTopics()
  const defaultContent = await readMemory()

  const contextParts: string[] = []

  if (topics?.length > 0) {
    const topicList = topics.map((topic: string) => `- ${topic}`).join('\n')
    contextParts.push(`<memory_topics>\n${topicList}\n</memory_topics>`)
  }

  if (defaultContent) {
    contextParts.push(`<memory topic=":default:">\n${defaultContent}\n</memory>`)
  }

  return contextParts.join('\n')
}

async function listTodoItems(
  input: { id?: string | null; status?: 'open' | 'completed' | 'closed' | null },
  context: ToolCallContext,
): Promise<TodoItem[]> {
  if (!context.toolProvider.listTodoItems) {
    throw new Error('To-do provider is not available')
  }
  return context.toolProvider.listTodoItems(input.id, input.status)
}

async function getTodoItem(input: { id: string }, context: ToolCallContext): Promise<TodoItem | undefined> {
  if (!context.toolProvider.getTodoItem) {
    throw new Error('To-do provider is not available')
  }
  return context.toolProvider.getTodoItem(input.id)
}

async function updateTodoItem(input: UpdateTodoItemInput, context: ToolCallContext): Promise<UpdateTodoItemOutput> {
  if (!context.toolProvider.updateTodoItem) {
    throw new Error('To-do provider is not available')
  }
  return context.toolProvider.updateTodoItem(input)
}

async function runAgent(input: AgentWorkflowInput, context: ToolCallContext) {
  const { logger, step, tools } = context.workflowContext
  if (!step || !tools) {
    throw new Error('Nested agent workflow context is not available')
  }
  return await agentWorkflow(input, { logger, step, tools })
}

/**
 * Wrapper for skill tool operations that handles context validation and error handling
 */
async function withSkillContext<_T>(
  context: ToolCallContext,
  fn: (skillContext: SkillContext) => Promise<ToolResponse>,
): Promise<ToolResponse> {
  if (!context.parameters.skillContext) {
    return {
      success: false,
      message: { type: 'error-text', value: 'Skill context not initialized' },
    }
  }

  try {
    return await fn(context.parameters.skillContext)
  } catch (error: unknown) {
    return {
      success: false,
      message: {
        type: 'error-text',
        value: error instanceof Error ? error.message : String(error),
      },
    }
  }
}

async function loadSkill(input: { skillName: string }, context: ToolCallContext): Promise<ToolResponse> {
  return withSkillContext(context, async (skillContext) => {
    const result = await coreLoadSkill(input, skillContext)
    if (!result.success || !result.skill) {
      return {
        success: false,
        message: { type: 'error-text', value: result.error ?? 'Failed to load skill' },
      }
    }
    return {
      success: true,
      message: {
        type: 'text',
        value: `Loaded skill '${result.skill.name}':\n\n${result.skill.content}\n\nAvailable files: ${result.skill.availableFiles.join(', ')}${result.warnings && result.warnings.length > 0 ? `\n\nWarnings:\n${result.warnings.join('\n')}` : ''}`,
      },
    }
  })
}

async function listSkills(input: { filter?: string }, context: ToolCallContext): Promise<ToolResponse> {
  return withSkillContext(context, async (skillContext) => {
    const result = await coreListSkills(input, skillContext)
    const skillsList = result.skills
      .map((skill: { name: string; description: string; source: string }) => {
        const sourceIcon = SOURCE_ICONS[skill.source as keyof typeof SOURCE_ICONS]
        return `${sourceIcon} **${skill.name}**: ${skill.description}`
      })
      .join('\n')

    return {
      success: true,
      message: {
        type: 'text',
        value: `Found ${result.total} skill${result.total === 1 ? '' : 's'}:\n\n${skillsList}`,
      },
    }
  })
}

async function readSkillFile(input: { skillName: string; filename: string }, context: ToolCallContext): Promise<ToolResponse> {
  return withSkillContext(context, async (skillContext) => {
    const result = await coreReadSkillFile(input, skillContext)
    if (!result.success || !result.content) {
      return {
        success: false,
        message: { type: 'error-text', value: result.error ?? 'Failed to read skill file' },
      }
    }
    return {
      success: true,
      message: { type: 'text', value: result.content },
    }
  })
}

